// One struct per event id; the id is the variant's index in id order (see eventId).
using Event = std::variant<
    SetLobbySlotEvent, DropUserEvent, StartGameEvent, DropOurselvesEvent, UserFinishedLoadingEvent,
    UserFinishedLoadingSyncEvent, SetGameDurationEvent, UserOptionsEvent, TurnEvent, BankFileEvent,
    BankSectionEvent, BankKeyEvent, BankValueEvent, BankSignatureEvent, CameraSaveEvent,
    PauseGameEvent, UnpauseGameEvent, SingleStepGameEvent, SetGameSpeedEvent, AddGameSpeedEvent,
    ReplayJumpEvent, SaveGameEvent, SaveGameDoneEvent, LoadGameDoneEvent, SessionCheatEvent,
    CommandManagerResetEvent, GameCheatEvent, CmdEvent, SelectionDeltaEvent,
    ControlGroupUpdateEvent, SelectionSyncCheckEvent, ResourceTradeEvent, TriggerChatMessageEvent,
    AICommunicateEvent, SetAbsoluteGameSpeedEvent, AddAbsoluteGameSpeedEvent, TriggerPingEvent,
    BroadcastCheatEvent, AllianceEvent, UnitClickEvent, UnitHighlightEvent,
    TriggerReplySelectedEvent, HijackReplaySessionEvent, HijackReplayGameEvent, TriggerSkippedEvent,
    TriggerSoundLengthQueryEvent, TriggerSoundOffsetEvent, TriggerTransmissionOffsetEvent,
    TriggerTransmissionCompleteEvent, CameraUpdateEvent, TriggerAbortMissionEvent,
    TriggerPurchaseMadeEvent, TriggerPurchaseExitEvent, TriggerPlanetMissionLaunchedEvent,
    TriggerPlanetPanelCanceledEvent, TriggerDialogControlEvent, TriggerSoundLengthSyncEvent,
    TriggerConversationSkippedEvent, TriggerMouseClickedEvent, TriggerMouseMovedEvent,
    AchievementAwardedEvent, TriggerHotkeyPressedEvent, TriggerTargetModeUpdateEvent,
    TriggerPlanetPanelReplayEvent, TriggerSoundtrackDoneEvent, TriggerPlanetMissionSelectedEvent,
    TriggerKeyPressedEvent, TriggerMovieFunctionEvent, TriggerPlanetPanelBirthCompleteEvent,
    TriggerPlanetPanelDeathCompleteEvent, ResourceRequestEvent, ResourceRequestFulfillEvent,
    ResourceRequestCancelEvent, TriggerResearchPanelExitEvent, TriggerResearchPanelPurchaseEvent,
    TriggerResearchPanelSelectionChangedEvent, TriggerCommandErrorEvent,
    TriggerMercenaryPanelExitEvent, TriggerMercenaryPanelPurchaseEvent,
    TriggerMercenaryPanelSelectionChangedEvent, TriggerVictoryPanelExitEvent,
    TriggerBattleReportPanelExitEvent, TriggerBattleReportPanelPlayMissionEvent,
    TriggerBattleReportPanelPlaySceneEvent, TriggerBattleReportPanelSelectionChangedEvent,
    TriggerVictoryPanelPlayMissionAgainEvent, TriggerMovieStartedEvent, TriggerMovieFinishedEvent,
    DecrementGameTimeRemainingEvent, TriggerPortraitLoadedEvent, TriggerCustomDialogDismissedEvent,
    TriggerGameMenuItemSelectedEvent, TriggerMouseWheelEvent,
    TriggerPurchasePanelSelectedPurchaseItemChangedEvent,
    TriggerPurchasePanelSelectedPurchaseCategoryChangedEvent, TriggerButtonPressedEvent,
    TriggerGameCreditsFinishedEvent, TriggerCutsceneBookmarkFiredEvent,
    TriggerCutsceneEndSceneFiredEvent, TriggerCutsceneConversationLineEvent,
    TriggerCutsceneConversationLineMissingEvent, GameUserLeaveEvent, GameUserJoinEvent,
    CommandManagerStateEvent, CmdUpdateTargetPointEvent, CmdUpdateTargetUnitEvent,
    TriggerAnimLengthQueryByNameEvent, TriggerAnimLengthQueryByPropsEvent, TriggerAnimOffsetEvent,
    CatalogModifyEvent, HeroTalentTreeSelectedEvent, TriggerProfilerLoggingFinishedEvent,
    HeroTalentTreeSelectionPanelToggledEvent, MuteChatEvent, PickMapTagEvent,
    ConvertToReplaySessionEvent, SetSyncLoadingTimeEvent, SetSyncPlayingTimeEvent,
    PeerSetSyncLoadingTimeEvent, PeerSetSyncPlayingTimeEvent>;

// The id of the event a variant holds.
[[nodiscard]] EventId eventId(const Event& event) noexcept;
[[nodiscard]] const char* eventName(EventId id) noexcept;

// The most m_gameEventData can hold.
inline constexpr std::size_t kEventDataMax = 1452;

// Writes the events back to back, each padded to a byte. False when a field is
// out of range or the result passes kEventDataMax.
[[nodiscard]] bool encodeEvents(std::span<const Event> events, std::vector<std::byte>& out);

struct EventsDecode {
    std::vector<Event> events;
    std::size_t consumed = 0; // bytes covered by `events`
    bool complete = false;    // every byte was an event
};

// Stops at the first event that does not decode; `complete` is then false.
[[nodiscard]] EventsDecode decodeEvents(std::span<const std::byte> data);

